def _load_fonts():
    raw = zlib.decompress(base64.b64decode(FONT_BLOB_B64))
    fonts = {}
    for key, (off, length) in FONT_INDEX.items():
        glyphs = {}
        pos = off
        end = off + length
        for ch in CHARSET:
            adv, w, h, xo, yo = raw[pos:pos + 5]
            pos += 5
            n = w * h
            glyphs[ch] = (adv, w, h, xo - 128, yo - 128,
                          raw[pos:pos + n])
            pos += n
        assert pos == end, key
        fonts[key] = glyphs
    return fonts


FONTS = _load_fonts()


class Font:
    """A rasterised font: glyph bitmaps + advances, blitted by hand."""

    def __init__(self, key):
        self.glyphs = FONTS[key]

    def width(self, text):
        return sum(self.glyphs.get(c, (0, 0, 0, 0, 0, b""))[0]
                   for c in text) / 4.0

    def draw(self, cv, x, y, text, color, alpha=255):
        pen = float(x)
        for ch in text:
            adv, w, h, xo, yo, bits = self.glyphs.get(
                ch, (0, 0, 0, 0, 0, b""))
            if w and h:
                cv.blit_bits(int(round(pen)) + xo, y + yo, w, h, bits,
                             color, alpha)
            pen += adv / 4.0


F_BIG = Font("serif_b19")
