# -- palette ----------------------------------------------------------------
CREAM = (248, 243, 228)
CREAM_R = (243, 237, 217)
COVER = (56, 50, 42)
INK = (26, 40, 68)
NAVY = (20, 50, 90)
GILT = (168, 126, 54)
MUTE = (98, 94, 82)
RULE_C = (152, 142, 120)


def shade(c1, c2, t):
    return tuple(round(c1[i] + (c2[i] - c1[i]) * t) for i in range(3))


# ---------------------------------------------------------------------------
# Pixel canvas: RGB buffer + alpha buffer, src-over compositing.
# ---------------------------------------------------------------------------
class Canvas:
    def __init__(self, w, h, fill=None):
        self.w = w
        self.h = h
        self.px = bytearray(w * h * 3)
        self.a = bytearray(w * h)
        if fill is not None:
            row = bytes(fill) * w
            for y in range(h):
                self.px[y * w * 3:(y + 1) * w * 3] = row
            self.a[:] = b"\xff" * (w * h)

    def put(self, x, y, color, alpha=255):
        """Src-over blend of one pixel."""
        if 0 <= x < self.w and 0 <= y < self.h:
            i = y * self.w + x
            if alpha >= 255 and self.a[i] >= 255:
                o = i * 3
                self.px[o:o + 3] = bytes(color)
                return
            o = i * 3
            sa = alpha
            da = self.a[i]
            out_a = sa + da * (255 - sa) // 255
            if out_a == 0:
                return
            for k in range(3):
                self.px[o + k] = (
                    color[k] * sa + self.px[o + k] * da * (255 - sa) // 255
                ) // max(1, out_a)
            self.a[i] = out_a

    def fill_rect(self, x0, y0, x1, y1, color, alpha=255):
        x0 = max(0, x0)
        y0 = max(0, y0)
        x1 = min(self.w, x1)
        y1 = min(self.h, y1)
        if x1 <= x0 or y1 <= y0:
            return
        if alpha >= 255:
            row = bytes(color) * (x1 - x0)
            for y in range(y0, y1):
                o = (y * self.w + x0) * 3
                self.px[o:o + 3 * (x1 - x0)] = row
            for y in range(y0, y1):
                o = y * self.w + x0
                self.a[o:o + (x1 - x0)] = b"\xff" * (x1 - x0)
            return
        for y in range(y0, y1):
            for x in range(x0, x1):
                self.put(x, y, color, alpha)

    def hline(self, x0, x1, y, color, width=1, alpha=255):
        for dy in range(-(width // 2), width - width // 2):
            self.fill_rect(x0, y + dy, x1, y + dy + 1, color, alpha)

    def line(self, x0, y0, x1, y1, color, width=1, alpha=255):
        """Bresenham line; width>1 stamps a disc at each step."""
        dx = abs(x1 - x0)
        dy = -abs(y1 - y0)
        sx = 1 if x0 < x1 else -1
        sy = 1 if y0 < y1 else -1
        err = dx + dy
        r = width // 2
        while True:
            if r <= 0:
                self.put(x0, y0, color, alpha)
            else:
                self.disc(x0, y0, r, color, alpha)
            if x0 == x1 and y0 == y1:
                break
            e2 = 2 * err
            if e2 >= dy:
                err += dy
                x0 += sx
            if e2 <= dx:
                err += dx
                y0 += sy

    def polyline(self, pts, color, width=1, alpha=255):
        for (x0, y0), (x1, y1) in zip(pts, pts[1:]):
            self.line(x0, y0, x1, y1, color, width, alpha)

    def disc(self, cx, cy, r, color, alpha=255):
        if r <= 0:
            self.put(cx, cy, color, alpha)
            return
        for y in range(cy - r, cy + r + 1):
            dx = int(math.sqrt(max(0, r * r - (y - cy) ** 2)))
            self.fill_rect(cx - dx, y, cx + dx + 1, y + 1, color, alpha)

    def ellipse_fill(self, x0, y0, x1, y1, color):
        cx = (x0 + x1) / 2.0
        cy = (y0 + y1) / 2.0
        rx = (x1 - x0) / 2.0
        ry = (y1 - y0) / 2.0
        if rx <= 0 or ry <= 0:
            return
        for y in range(y0, y1 + 1):
            t = (y - cy) / ry
            if abs(t) > 1:
                continue
            dx = int(rx * math.sqrt(max(0.0, 1.0 - t * t)))
            self.fill_rect(int(cx - dx), y, int(cx + dx) + 1, y + 1, color)

    def ellipse_outline(self, x0, y0, x1, y1, color, width=1, alpha=255):
        cx = (x0 + x1) / 2.0
        cy = (y0 + y1) / 2.0
        rx = (x1 - x0) / 2.0
        ry = (y1 - y0) / 2.0
        steps = max(48, int(2 * math.pi * max(rx, ry)))
        pts = [(round(cx + rx * math.cos(2 * math.pi * i / steps)),
                round(cy + ry * math.sin(2 * math.pi * i / steps)))
               for i in range(steps + 1)]
        self.polyline(pts, color, width, alpha)

    def arc(self, x0, y0, x1, y1, a0, a1, color, width=1, alpha=255):
        """Outline arc, angles in degrees, 0=east, clockwise (y down)."""
        cx = (x0 + x1) / 2.0
        cy = (y0 + y1) / 2.0
        rx = (x1 - x0) / 2.0
        ry = (y1 - y0) / 2.0
        span = (a1 - a0) % 360 or 360
        steps = max(4, int(span / 3))
        pts = []
        for i in range(steps + 1):
            a = math.radians(a0 + span * i / steps)
            pts.append((round(cx + rx * math.cos(a)),
                        round(cy + ry * math.sin(a))))
        self.polyline(pts, color, width, alpha)

    def pie_fill(self, x0, y0, x1, y1, a0, a1, color):
        """Filled pie slice; angles as in arc()."""
        cx = (x0 + x1) / 2.0
        cy = (y0 + y1) / 2.0
        rx = (x1 - x0) / 2.0
        ry = (y1 - y0) / 2.0
        span = (a1 - a0) % 360 or 360
        steps = max(4, int(span / 3))
        pts = [(round(cx), round(cy))]
        for i in range(steps + 1):
            a = math.radians(a0 + span * i / steps)
            pts.append((round(cx + rx * math.cos(a)),
                        round(cy + ry * math.sin(a))))
        self.polygon_fill(pts, color)

    def polygon_fill(self, pts, color):
        """Even-odd scanline polygon fill."""
        pts = [(int(round(x)), int(round(y))) for x, y in pts]
        if len(pts) < 3:
            return
        ys = [p[1] for p in pts]
        for y in range(max(0, min(ys)), min(self.h, max(ys) + 1)):
            xs = []
            n = len(pts)
            for i in range(n):
                x0, y0 = pts[i]
                x1, y1 = pts[(i + 1) % n]
                if (y0 <= y < y1) or (y1 <= y < y0):
                    xs.append(x0 + (y - y0) * (x1 - x0) / (y1 - y0))
            xs.sort()
            for j in range(0, len(xs) - 1, 2):
                self.fill_rect(int(math.ceil(xs[j])), y,
                               int(math.floor(xs[j + 1])) + 1, y + 1,
                               color)

    def polygon_outline(self, pts, color, width=1):
        self.polyline(pts + [pts[0]], color, width)

    def rounded_rect(self, x0, y0, x1, y1, radius, color):
        self.fill_rect(x0 + radius, y0, x1 - radius, y1, color)
        self.fill_rect(x0, y0 + radius, x1, y1 - radius, color)
        for cx, cy in ((x0 + radius, y0 + radius),
                       (x1 - radius, y0 + radius),
                       (x0 + radius, y1 - radius),
                       (x1 - radius, y1 - radius)):
            self.disc(cx, cy, radius, color)

    def rect_outline(self, x0, y0, x1, y1, color, width=1, alpha=255):
        for k in range(width):
            self.fill_rect(x0 + k, y0 + k, x1 - k, y0 + k + 1, color, alpha)
            self.fill_rect(x0 + k, y1 - k - 1, x1 - k, y1 - k, color, alpha)
            self.fill_rect(x0 + k, y0 + k, x0 + k + 1, y1 - k, color, alpha)
            self.fill_rect(x1 - k - 1, y0 + k, x1 - k, y1 - k, color, alpha)

    def blit_bits(self, x0, y0, w, h, bits, color, alpha=255):
        """Stamp a grayscale glyph bitmap (0=transparent) over the canvas."""
        for gy in range(h):
            y = y0 + gy
            if y < 0 or y >= self.h:
                continue
            row = gy * w
            for gx in range(w):
                v = bits[row + gx]
                if v:
                    self.put(x0 + gx, y, color, v * alpha // 255)

    def paste(self, src, dx, dy, scale=1.0):
        """Src-over paste of another canvas, with a global alpha scale."""
        for y in range(src.h):
            ty = dy + y
            if ty < 0 or ty >= self.h:
                continue
            for x in range(src.w):
                tx = dx + x
                if tx < 0 or tx >= self.w:
                    continue
                si = y * src.w + x
                a = src.a[si]
                if a == 0 or scale <= 0:
                    continue
                o = si * 3
                self.put(tx, ty,
                         (src.px[o], src.px[o + 1], src.px[o + 2]),
                         int(a * scale))

    def rotate(self, angle_deg):
        """Nearest-neighbour rotation about the centre, expanded canvas."""
        a = math.radians(angle_deg)
        ca, sa = math.cos(a), math.sin(a)
        nw = int(abs(self.w * ca) + abs(self.h * sa)) + 1
        nh = int(abs(self.w * sa) + abs(self.h * ca)) + 1
        out = Canvas(nw, nh)
        cx, cy = self.w / 2.0, self.h / 2.0
        ox, oy = nw / 2.0, nh / 2.0
        for y in range(nh):
            for x in range(nw):
                sx = ca * (x - ox) + sa * (y - oy) + cx
                sy = -sa * (x - ox) + ca * (y - oy) + cy
                ix, iy = int(round(sx)), int(round(sy))
                if 0 <= ix < self.w and 0 <= iy < self.h:
                    si = iy * self.w + ix
                    if self.a[si]:
                        oi = y * nw + x
                        oo = oi * 3
                        so = si * 3
                        out.px[oo:oo + 3] = self.px[so:so + 3]
                        out.a[oi] = self.a[si]
        return out


# ---------------------------------------------------------------------------
# PNG encoder: IHDR + IDAT (zlib, per-row best filter) + IEND.
# ---------------------------------------------------------------------------
def _paeth(a, b, c):
    p = a + b - c
    pa, pb, pc = abs(p - a), abs(p - b), abs(p - c)
    if pa <= pb and pa <= pc:
        return a
    if pb <= pc:
        return b
    return c


def _filter_row(kind, row, prev):
    out = bytearray(len(row))
    if kind == 0:
        out[:] = row
    elif kind == 1:
        for i, v in enumerate(row):
            left = row[i - 3] if i >= 3 else 0
            out[i] = (v - left) & 0xFF
    elif kind == 2:
        for i, v in enumerate(row):
            out[i] = (v - prev[i]) & 0xFF
    elif kind == 3:
        for i, v in enumerate(row):
            left = row[i - 3] if i >= 3 else 0
            out[i] = (v - ((left + prev[i]) >> 1)) & 0xFF
    else:
        for i, v in enumerate(row):
            left = row[i - 3] if i >= 3 else 0
            up = prev[i]
            up_left = prev[i - 3] if i >= 3 else 0
            out[i] = (v - _paeth(left, up, up_left)) & 0xFF
    return bytes(out)


def _signed_cost(data):
    return sum(v if v < 128 else 256 - v for v in data)


def write_png(cv, path):
    w, h = cv.w, cv.h

    def encode(adaptive):
        raw = bytearray()
        prev = bytes(w * 3)
        for y in range(h):
            row = bytes(cv.px[y * w * 3:(y + 1) * w * 3])
            if not adaptive:
                raw.append(0)
                raw += row
            else:
                best = None
                for kind in range(5):
                    cand = _filter_row(kind, row, prev)
                    cost = _signed_cost(cand)
                    if best is None or cost < best[0]:
                        best = (cost, kind, cand)
                raw.append(best[1])
                raw += best[2]
            prev = row
        return bytes(raw)

    ihdr = struct.pack(">IIBBBBB", w, h, 8, 2, 0, 0, 0)

    def chunk(tag, data):
        return (struct.pack(">I", len(data)) + tag + data +
                struct.pack(">I", zlib.crc32(tag + data) & 0xFFFFFFFF))

    def assemble(raw):
        return (b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", ihdr) +
                chunk(b"IDAT", zlib.compress(raw, 9)) +
                chunk(b"IEND", b""))

    png = assemble(encode(adaptive=False))
    if len(png) > 1048576:  # 1 MiB cap: retry with per-row best filters
        png = assemble(encode(adaptive=True))
    with open(path, "wb") as f:
        f.write(png)
    return len(png)


# -- ICAO machine-readable zone ---------------------------------------------
def icao_check(field):
    """TD3 check digit: values A=10..Z=35, '<'=0, weights 7/3/1."""
    total = 0
    for i, ch in enumerate(field):
        if ch == "<":
            val = 0
        elif ch.isdigit():
            val = int(ch)
        else:
            val = ord(ch) - 55
        total += val * (7, 3, 1)[i % 3]
    return str(total % 10)


def mrz_pair():
    top = "P<KLDHALVORSEN<<INGRID<MARIE"
    top = top + "<" * (44 - len(top))
    doc = "0048217<<"                       # document number + filler
    dob, sex, exp = "940314", "F", "360601"  # 14 Mar 1994 / 01 Jun 2036
    optional = "<" * 14
    line2 = (doc + icao_check(doc) + "KLD" + dob + icao_check(dob)
             + sex + exp + icao_check(exp) + optional + icao_check(optional))
    # Composite check digit (ICAO 9303): over doc+cd, dob+cd, exp+cd,
    # optional+cd only -- nationality and sex are NOT part of it.
    composite = (doc + icao_check(doc) + dob + icao_check(dob)
                 + exp + icao_check(exp) + optional + icao_check(optional))
    bottom = line2 + icao_check(composite)
    assert len(top) == 44 and len(bottom) == 44
    return top, bottom


# -- coat of arms ------------------------------------------------------------
def crest(cv, cx, cy, s):
    """Shield with three sea-waves under a four-point north star."""
    pts = [(cx - s, cy - s), (cx + s, cy - s), (cx + s, cy + s * 0.45),
           (cx, cy + s * 1.2), (cx - s, cy + s * 0.45)]
    cv.polygon_outline([(int(x), int(y)) for x, y in pts], GILT, 3)
    inner = [(cx - s + 5, cy - s + 5), (cx + s - 5, cy - s + 5),
             (cx + s - 5, cy + s * 0.45 - 2), (cx, cy + s - 5),
             (cx - s + 5, cy + s * 0.45 - 2)]
    cv.polygon_fill([(int(x), int(y)) for x, y in inner], (229, 233, 239))
    for k, wy in enumerate((-0.3, 0.05, 0.4)):
        wave = [(x, int(cy + s * wy + 3 * math.sin((x - cx) / 9.0 + k)))
                for x in range(cx - s + 9, cx + s - 7, 4)]
        cv.polyline(wave, NAVY, 2)
    cv.polygon_fill([(cx, cy - s), (cx + 3, cy - s * 0.66),
                     (cx, cy - s * 0.48), (cx - 3, cy - s * 0.66)], GILT)


def guilloche(cv, x0, y0, x1, y1, colour, gap=7):
    """Faint wavy security print."""
    for yy in range(y0, y1, gap):
        pts = [(x, yy + 2 * math.sin((x - x0) / 44.0))
               for x in range(x0, x1 + 1, 8)]
        cv.polyline([(int(x), int(y)) for x, y in pts], colour, 1)


# -- portrait ----------------------------------------------------------------
def photo(cv, x0, y0, x1, y1):
    """Flat vector passport portrait: woman, centre-parted dark hair,
    navy coat, plain grey-blue backdrop."""
    cx = (x0 + x1) // 2
    w, h = x1 - x0, y1 - y0
    for y in range(y0, y1):
        t = (y - y0) / max(1, h)
        cv.fill_rect(x0, y, x1, y + 1,
                     shade((216, 223, 228), (184, 194, 204), t))
    skin, skin_d, skin_l = (217, 173, 137), (199, 153, 119), (229, 189, 153)
    hair, hair_d = (90, 54, 36), (68, 40, 26)
    coat = (40, 54, 80)
    # coat and shoulders
    cv.pie_fill(cx - 90, y1 - 120, cx + 90, y1 + 42, 180, 360, coat)
    cv.fill_rect(x0, y1 - 44, x1, y1, coat)
    # white shirt V and collar
    cv.polygon_fill([(cx - 27, y1 - 54), (cx + 27, y1 - 54), (cx, y1 - 6)],
                    (241, 239, 231))
    cv.polygon_fill([(cx - 31, y1 - 60), (cx - 9, y1 - 35), (cx - 2, y1 - 54)],
                    (227, 225, 217))
    cv.polygon_fill([(cx + 31, y1 - 60), (cx + 9, y1 - 35), (cx + 2, y1 - 54)],
                    (227, 225, 217))
    # neck
    cv.fill_rect(cx - 21, y1 - 110, cx + 21, y1 - 54, skin_d)
    cv.fill_rect(cx - 21, y1 - 110, cx + 21, y1 - 97, (191, 145, 111))
    # head
    hx0, hy0, hx1, hy1 = cx - 53, y0 + 28, cx + 53, y0 + 150
    # hair mass behind the head, falling to the shoulders
    cv.pie_fill(hx0 - 12, hy0 - 18, hx1 + 12, hy0 + 80, 180, 360, hair)
    cv.rounded_rect(hx0 - 11, hy0 + 56, hx0 - 3, y0 + 168, 4, hair)
    cv.rounded_rect(hx1 + 3, hy0 + 56, hx1 + 11, y0 + 168, 4, hair)
    cv.ellipse_fill(hx0, hy0, hx1, hy1, skin)
    # cheek light
    cv.ellipse_fill(hx0 + 7, hy0 + 64, hx0 + 35, hy0 + 98, skin_l)
    cv.ellipse_fill(hx1 - 35, hy0 + 64, hx1 - 7, hy0 + 98, skin_l)
    # ears
    cv.ellipse_fill(hx0 - 9, hy0 + 60, hx0 + 7, hy0 + 90, skin)
    cv.ellipse_fill(hx1 - 7, hy0 + 60, hx1 + 9, hy0 + 90, skin)
    # fringe, swept to the sides from a centre part
    cv.pie_fill(hx0 - 7, hy0 - 12, hx1 + 7, hy0 + 68, 180, 332, hair)
    cv.pie_fill(hx0 - 7, hy0 - 12, hx1 + 7, hy0 + 68, 196, 346, hair_d)
    cv.line(cx, hy0 + 2, cx, hy0 + 28, hair_d, 2)
    # brows
    cv.arc(cx - 35, hy0 + 58, cx - 9, hy0 + 74, 200, 340, (72, 46, 32), 3)
    cv.arc(cx + 9, hy0 + 58, cx + 35, hy0 + 74, 200, 340, (72, 46, 32), 3)
    # eyes: white, iris, pupil, highlight, and a short lash arc above
    for ex in (cx - 22, cx + 22):
        cv.ellipse_fill(ex - 11, hy0 + 76, ex + 11, hy0 + 90, (246, 243, 237))
        cv.ellipse_fill(ex - 5, hy0 + 77, ex + 5, hy0 + 89, (98, 68, 46))
        cv.ellipse_fill(ex - 2, hy0 + 80, ex + 2, hy0 + 86, (22, 18, 16))
        cv.ellipse_fill(ex + 2, hy0 + 78, ex + 5, hy0 + 81, (255, 255, 255))
        cv.arc(ex - 11, hy0 + 72, ex + 11, hy0 + 86, 200, 340, (72, 46, 32), 2)
    # nose and mouth: one gentle closed-lip curve
    cv.line(cx + 1, hy0 + 90, cx - 2, hy0 + 110, skin_d, 2)
    cv.arc(cx - 6, hy0 + 106, cx + 8, hy0 + 116, 0, 180, skin_d, 2)
    cv.arc(cx - 13, hy0 + 118, cx + 13, hy0 + 132, 0, 180, (166, 98, 86), 2)
    cv.arc(hx0 + 9, hy0 + 98, hx1 - 9, hy1 - 2, 20, 160, skin_d, 2)


# -- rubber stamps ------------------------------------------------------------
def round_stamp(img, cx, cy, r, ink, top, mid, bot, tilt=0):
    """Circular border-control stamp, drawn on a transparent layer and
    rotated so it sits slightly askew like a real hand stamp."""
    size = r * 2 + 26
    layer = Canvas(size, size)
    col = ink
    c = size // 2
    layer.ellipse_outline(c - r, c - r, c + r, c + r, col, 3, alpha=212)
    layer.ellipse_outline(c - r + 9, c - r + 9, c + r - 9, c + r - 9,
                          col, 1, alpha=212)

    # Top lines sit near the circle's edge, where the chord is narrow:
    # shrink the font, and if even the smallest is wider than the
    # chord at the glyphs' top edge, slide the line down until the
    # chord clears it.
    y = c - r + 24
    top_items = []
    for txt, fnt in top:
        use, yy = F_ST4, y
        for cand in (F_ST, F_ST2, F_ST3, F_ST4):
            wdt = cand.width(txt)
            half = (wdt + 16) / 2.0
            if half >= r:
                continue
            y_need = math.ceil(c - math.sqrt(r * r - half * half))
            if y_need - y <= 20:
                use, yy = cand, max(y, y_need)
                break
        else:
            wdt = F_ST4.width(txt)
            half = (wdt + 16) / 2.0
            if half < r:
                yy = max(y, math.ceil(c - math.sqrt(r * r - half * half)))
        top_items.append((txt, use, yy))
        y = yy + 13

    # Vertical fit: the last line must end inside the inner ring.
    # Tighten the mid/bot steps (never below 11) until it does.
    step_mid, step_bot = 15, 13
    while step_mid > 11 or step_bot > 11:
        if bot:
            end = (y + len(mid) * step_mid
                   + (len(bot) - 1) * step_bot + 10)
        else:
            end = y + max(0, len(mid) - 1) * step_mid + 10
        if end <= c + r - 10:
            break
        if step_mid > 11:
            step_mid -= 1
        elif step_bot > 11:
            step_bot -= 1

    for txt, use, yy in top_items:
        tw = use.width(txt)
        use.draw(layer, int(c - tw / 2), yy, txt, col, alpha=212)
    for txt, fnt in mid:
        tw = fnt.width(txt)
        fnt.draw(layer, int(c - tw / 2), y, txt, col, alpha=212)
        y += step_mid
    for txt, fnt in bot:
        tw = fnt.width(txt)
        fnt.draw(layer, int(c - tw / 2), y, txt, col, alpha=212)
        y += step_bot
    rot = layer.rotate(tilt)
    img.paste(rot, cx - rot.w // 2, cy - rot.h // 2)


def box_stamp(img, x, y, w, h, ink, title, rows, tilt=0):
    layer = Canvas(w + 26, h + 26)
    col = ink
    layer.rect_outline(11, 11, 11 + w, 11 + h, col, 3, alpha=212)
    layer.hline(11, 11 + w, 35, col, 1, alpha=212)
    title_fnt = F_ST
    for cand in (F_ST, F_ST2, F_ST3):
        if cand.width(title) <= w - 10:
            title_fnt = cand
            break
    tw = title_fnt.width(title)
    title_fnt.draw(layer, int(11 + (w - tw) / 2), 15, title, col, alpha=212)
    yy = 43
    for row in rows:
        tw = F_ST2.width(row)
        F_ST2.draw(layer, int(11 + (w - tw) / 2), yy, row, col, alpha=212)
        yy += 15
    rot = layer.rotate(tilt)
    img.paste(rot, x - 13, y - 13)


def text_lines(text, font, width):
    """Greedy word wrap, returns a list of lines fitting `width`."""
    out, cur = [], ""
    for word in text.split():
        trial = (cur + " " + word).strip()
        if font.width(trial) <= width:
            cur = trial
        else:
            if cur:
                out.append(cur)
            cur = word
    if cur:
        out.append(cur)
    return out


# -- the spread ---------------------------------------------------------------
def build():
    img = Canvas(SIZE, SIZE, COVER)
    # two cream leaves, dark gutter between them
    img.fill_rect(6, 6, 1018, 1018, CREAM)
    img.fill_rect(6, 6, 508, 1018, CREAM)
    img.fill_rect(516, 6, 1018, 1018, CREAM_R)
    img.fill_rect(508, 6, 516, 1018, (122, 112, 94))
    img.fill_rect(512, 6, 513, 1018, (92, 84, 68))

    # =============== LEFT LEAF: DATA PAGE ===============
